<script setup>
import { computed, ref } from 'vue'
import PageHeader from '@/components/ui/PageHeader.vue'
import { useActionFeedback } from '@/composables/useActionFeedback'
const { notify } = useActionFeedback()
const searchQuery = ref(''); const statusFilter = ref('all'); const modal = ref(null); const selected = ref(null)
const tasks = ref([{ id:1,title:'Design homepage mockup',project:'Website Redesign',assignee:'John Doe',status:'completed',priority:'high',dueDate:'2024-12-05'},{id:2,title:'Implement user authentication',project:'Mobile App',assignee:'Jane Smith',status:'in-progress',priority:'high',dueDate:'2024-12-08'},{id:3,title:'Write API documentation',project:'CRM Integration',assignee:'Mike Johnson',status:'pending',priority:'medium',dueDate:'2024-12-10'},{id:4,title:'Fix responsive issues',project:'Website Redesign',assignee:'Sarah Wilson',status:'in-progress',priority:'low',dueDate:'2024-12-12'}])
const draft = ref({ title:'', project:'', assignee:'', status:'pending', priority:'medium', dueDate:'' })
const filteredTasks = computed(() => tasks.value.filter(t => (`${t.title} ${t.project} ${t.assignee}`).toLowerCase().includes(searchQuery.value.toLowerCase()) && (statusFilter.value === 'all' || t.status === statusFilter.value)))
const statusClass = s => ({completed:'bg-success/10 text-success','in-progress':'bg-primary/10 text-primary',pending:'bg-warning/10 text-warning'})[s]
const priorityClass = p => ({high:'bg-danger/10 text-danger',medium:'bg-warning/10 text-warning',low:'bg-success/10 text-success'})[p]
const openNew = () => { selected.value = null; draft.value = {title:'',project:'',assignee:'',status:'pending',priority:'medium',dueDate:''}; modal.value = 'edit' }
const openEdit = task => { selected.value = task; draft.value = {...task}; modal.value = 'edit' }
const save = () => { if (!draft.value.title.trim()) return; if (selected.value) Object.assign(selected.value, draft.value); else tasks.value.unshift({ ...draft.value, id: Date.now() }); modal.value = null; notify(selected.value ? 'Task updated.' : 'Task created.') }
const remove = task => { tasks.value = tasks.value.filter(t => t.id !== task.id); modal.value = null; notify('Task deleted.') }
const changeStatus = task => { const statuses=['pending','in-progress','completed']; task.status=statuses[(statuses.indexOf(task.status)+1)%statuses.length]; notify(`Task moved to ${task.status.replace('-', ' ')}.`) }
</script>
<template><div><PageHeader title="Task List" subtitle="Manage all tasks across projects"><template #actions><button class="ti-btn ti-btn-primary" data-feedback-handled="true" @click="openNew"><i class="ri-add-line me-1"></i> New Task</button></template></PageHeader><div class="box"><div class="box-header flex flex-wrap items-center justify-between gap-4"><div class="flex items-center gap-3"><div class="relative"><input v-model="searchQuery" class="ti-form-control !ps-10" placeholder="Search tasks..."><i class="ri-search-line absolute start-3 top-1/2 -translate-y-1/2 text-textmuted"></i></div><select v-model="statusFilter" class="ti-form-select w-auto"><option value="all">All Status</option><option value="pending">Pending</option><option value="in-progress">In Progress</option><option value="completed">Completed</option></select></div></div><div class="box-body p-0"><div class="table-responsive"><table class="table table-hover whitespace-nowrap"><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Status</th><th>Priority</th><th>Due Date</th><th>Actions</th></tr></thead><tbody><tr v-for="task in filteredTasks" :key="task.id"><td class="font-medium">{{task.title}}</td><td class="text-textmuted">{{task.project}}</td><td>{{task.assignee}}</td><td><button class="badge" :class="statusClass(task.status)" data-feedback-handled="true" @click="changeStatus(task)">{{task.status}}</button></td><td><span class="badge" :class="priorityClass(task.priority)">{{task.priority}}</span></td><td>{{task.dueDate}}</td><td><div class="flex gap-1"><button class="ti-btn ti-btn-soft-primary ti-btn-icon ti-btn-sm" data-feedback-handled="true" aria-label="View task" @click="selected=task;modal='view'"><i class="ri-eye-line"></i></button><button class="ti-btn ti-btn-soft-info ti-btn-icon ti-btn-sm" data-feedback-handled="true" aria-label="Edit task" @click="openEdit(task)"><i class="ri-edit-line"></i></button><button class="ti-btn ti-btn-soft-danger ti-btn-icon ti-btn-sm" data-feedback-handled="true" aria-label="Delete task" @click="selected=task;modal='delete'"><i class="ri-delete-bin-line"></i></button></div></td></tr></tbody></table></div></div></div><div v-if="modal" class="fixed inset-0 z-[80] flex items-center justify-center bg-black/40" @click.self="modal=null"><div class="bg-white dark:bg-bgdark rounded-xl shadow-xl w-full max-w-md mx-4"><div class="px-6 py-4 border-b flex justify-between"><h3 class="font-semibold">{{modal==='edit'?(selected?'Edit Task':'New Task'):modal==='delete'?'Delete Task':'Task details'}}</h3><button class="ti-btn ti-btn-sm ti-btn-light" @click="modal=null">Close</button></div><div class="p-6" v-if="modal==='edit'"><label class="ti-form-label">Title</label><input v-model="draft.title" class="ti-form-control mb-3"><label class="ti-form-label">Project</label><input v-model="draft.project" class="ti-form-control mb-3"><label class="ti-form-label">Assignee</label><input v-model="draft.assignee" class="ti-form-control mb-3"><label class="ti-form-label">Status</label><select v-model="draft.status" class="ti-form-select"><option value="pending">Pending</option><option value="in-progress">In Progress</option><option value="completed">Completed</option></select></div><div class="p-6" v-else-if="modal==='view'"><p><b>{{selected.title}}</b></p><p class="text-textmuted">{{selected.project}} · {{selected.assignee}} · Due {{selected.dueDate}}</p></div><div class="p-6" v-else>Delete <b>{{selected.title}}</b>? This removes it from the current list.</div><div class="px-6 py-4 border-t flex justify-end gap-2"><button class="ti-btn ti-btn-light" @click="modal=null">Cancel</button><button v-if="modal==='edit'" class="ti-btn ti-btn-primary" @click="save">Save Task</button><button v-if="modal==='delete'" class="ti-btn ti-btn-danger" @click="remove(selected)">Delete</button></div></div></div></div></template>
